SELECT v.`id`, 'electricidad', 'ele_centralita_estrategia', 'Centralita: estrategia', 'Densidad-velocidad: calcula el combustible con la presión del colector (MAP) y las rpm, y lo corrige en lazo cerrado con la sonda lambda · Correcciones por temperatura del aire, del refrigerante, mariposa, tensión de batería y sonda lambda. Corte de inyección en retención y a altas rpm · Encendido estático de chispa perdida: dos bobinas, una para los cilindros 1+4 y otra para 2+3, sin delco. Avance calculado con MAP, rpm y temperatura · Rueda fónica de 60-2 dientes en la polea del cigüeñal · Bomba de gasolina por relé, mandado por la centralita (se activa un momento al dar el contacto) · Purga del cánister de carbón activo hacia la admisión mediante electroválvula', NULL, NULL, 'Fiabilidad B · Doc. Marelli IAW 16F', 0 FROM `vehiculos` v WHERE v.`id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB'))
ON CONFLICT(`vehiculo_id`, `clave`) DO UPDATE SET `seccion` = excluded.`seccion`, `nombre` = excluded.`nombre`, `valor` = excluded.`valor`, `unidad` = excluded.`unidad`, `detalle` = excluded.`detalle`, `fuente` = excluded.`fuente`, `verificado` = excluded.`verificado`, `actualizado` = datetime('now')
WHERE `datos_tecnicos`.`verificado` = 0;
