SELECT v.`id`, 'electricidad', 'ele_centralita_modo_de_emergencia', 'Centralita: modo de emergencia', 'Fallo del motor paso a paso: lo desactiva y limita el motor a 1200 rpm · Fallo del MAP: usa presión atmosférica fija (1012 mbar) · Fallo de la mariposa (TPS): calcula la posición con el MAP y las rpm · Fallo de temperatura de aire o refrigerante: último valor válido o un valor por defecto · Sin señal de rpm/PMS: el motor no arranca (no hay modo de emergencia) · Batería fuera de rango: avería si pasa de 16,2 V o baja de 6 V', NULL, NULL, 'Fiabilidad B · Doc. Marelli IAW 16F', 0 FROM `vehiculos` v WHERE v.`id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB'))
