INSERT INTO `procedimientos` (`vehiculo_id`, `titulo`, `tiempo_min`, `herramientas`, `pasos`, `notas`)
SELECT v.`id`, 'Comprobar el pineado de la centralita (IAW 16F → 16S.S0)', 120, '["Polímetro", "Puntas finas para pinchar por detrás", "Esquema de la sección 9.5"]', '[{"texto": "Pin 1 · Bobina 1, cilindros 1+4 (mando a masa) (blanco/verde): Sin contacto y conector suelto: entre el pin y el borne + de la bobina, 0,5-0,6 Ω (el primario). Ojo: la alimentación de la bobina puede venir del relé principal, que no se activa con la centralita desenchufada.", "par": null}, {"texto": "Pin 2 · Motor paso a paso, fase B (verde): Las cuatro fases forman dos bobinados: busca la pareja con 45-65 Ω entre sí.", "par": null}, {"texto": "Pin 3 · Motor paso a paso, fase D (azul/amarillo): Ídem. Entre fases de bobinados distintos no debe haber continuidad.", "par": null}, {"texto": "Pin 4 · Mando del relé principal (mantenimiento de alimentación) (azul/rojo): Continuidad con la bobina del relé principal.", "par": null}, {"texto": "Pin 5 · Entrada de cambio automático: No se usa con cambio manual.", "par": null}, {"texto": "Pin 6 · Testigo de inyección (mando a masa) (gris/rojo): Contacto dado y conector suelto: ~12 V a través de la bombilla del testigo.", "par": null}, {"texto": "Pin 7 · Inmovilizador: línea serie con el cajetín: Continuidad con el conector del cajetín del inmovilizador. Es el único cable entre los dos.", "par": null}, {"texto": "Pin 8 · Relé del aire acondicionado (+) (verde): Sin A/A suele estar vacío.", "par": null}, {"texto": "Pin 9 · Sin conectar: ", "par": null}, {"texto": "Pin 10 · Diagnosis, línea L (azul claro/azul): Continuidad con el conector de diagnosis de 3 pines.", "par": null}, {"texto": "Pin 11 · Sensor PMS (−) (azul/rojo): Entre 11 y 28: 575-720 Ω (la resistencia del sensor).", "par": null}, {"texto": "Pin 12 · Sonda lambda (−) (marrón/verde): Continuidad con la masa de señal de la sonda.", "par": null}, {"texto": "Pin 13 · Sensor de temperatura del refrigerante (violeta/blanco): Entre 13 y la masa de sensores: resistencia del NTC, baja al calentarse. Enchufado y con contacto: 2-3 V en frío.", "par": null}, {"texto": "Pin 14 · Alimentación de sensores +5 V (azul claro/negro): Enchufado y con contacto: 5,0 V respecto a masa.", "par": null}, {"texto": "Pin 15 · Diagnosis, línea K (blanco/rojo): Continuidad con el conector de diagnosis de 3 pines.", "par": null}, {"texto": "Pin 16 · Masa de señales (negro): Conector suelto: continuidad a masa del motor (< 1 Ω).", "par": null}, {"texto": "Pin 17 · Masa principal (motor) (verde/negro (dudoso)): Conector suelto: continuidad a masa del motor (< 1 Ω).", "par": null}, {"texto": "Pin 18 · Inyector (mando a masa) (rosa/negro): Sin contacto y conector suelto: entre el pin y la alimentación del inyector, unos 1,75 Ω (el inyector) más el cable.", "par": null}, {"texto": "Pin 19 · Bobina 2, cilindros 2+3 (mando a masa) (azul claro/rojo): Como el pin 1, con la otra bobina.", "par": null}, {"texto": "Pin 20 · Motor paso a paso, fase A (azul/blanco): Como el pin 2.", "par": null}, {"texto": "Pin 21 · Motor paso a paso, fase C (blanco): Como el pin 2.", "par": null}, {"texto": "Pin 22 · Electroválvula del cánister (mando a masa) (naranja/negro): Entre el pin y su alimentación: 25-55 Ω.", "par": null}, {"texto": "Pin 23 · Relé de la bomba de gasolina (mando a masa) (negro/violeta): Continuidad con la bobina del relé de la bomba. Puentear a masa con contacto dado debe hacer sonar la bomba.", "par": null}, {"texto": "Pin 24 · Relé del aire acondicionado (−) (amarillo): Sin A/A suele estar vacío.", "par": null}, {"texto": "Pin 25 · Sin conectar: ", "par": null}, {"texto": "Pin 26 · Positivo de contacto (+15) (naranja (dudoso)): ~12 V solo con el contacto dado.", "par": null}, {"texto": "Pin 27 · Sin conectar: ", "par": null}, {"texto": "Pin 28 · Sensor PMS (+) (amarillo/negro): Con 11: 575-720 Ω. Al dar arranque, señal alterna de unos voltios.", "par": null}, {"texto": "Pin 29 · Sonda lambda (señal +) (azul/amarillo): Motor caliente al ralentí: oscila entre ~0,1 y ~0,9 V.", "par": null}, {"texto": "Pin 30 · Potenciómetro de mariposa (señal) (rosa): Enchufado y con contacto: ~0,3 V cerrada y sube sin saltos hasta ~4,5 V abierta.", "par": null}, {"texto": "Pin 31 · Sensor de temperatura del aire (violeta): Entre 31 y la masa de sensores: unos 2,5 kΩ a 20 °C.", "par": null}, {"texto": "Pin 32 · Sensor MAP (señal) (amarillo/rojo): Contacto dado sin arrancar: ~4,5 V (presión atmosférica). Al ralentí baja mucho.", "par": null}, {"texto": "Pin 33 · Sin conectar: ", "par": null}, {"texto": "Pin 34 · Masa secundaria (motor) (gris/negro): Conector suelto: continuidad a masa del motor (< 1 Ω).", "par": null}, {"texto": "Pin 35 · Alimentación desde el relé principal (+30) (marrón/blanco): ~12 V con el relé principal activado (motor arrancando o en marcha). Con el conector suelto, el relé no entra.", "par": null}]', 'Patillaje de la IAW 16F (Cinquecento/Seicento 899): punto de partida para tu 16S.S0. Resistencias y continuidades con el contacto quitado y el conector suelto (lado del mazo); tensiones con el conector enchufado. Fiabilidad C hasta comprobarlo. 35 pines (16F). En la 16S.S0 sin confirmar: cuéntalos.' FROM `vehiculos` v WHERE v.`id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB'))
AND NOT EXISTS (SELECT 1 FROM `procedimientos` x WHERE x.`vehiculo_id` = v.`id` AND x.`titulo` = 'Comprobar el pineado de la centralita (IAW 16F → 16S.S0)');
--> statement-breakpoint
