SELECT v.`id`, 'Averías típicas del motor SPI', NULL, '["Polímetro", "Lámpara de pruebas"]', '[{"texto": "Se cala en caliente y no arranca hasta que se enfría: sensor PMS. A menudo no deja código.", "par": null}, {"texto": "CO alto, mezcla rica o suspende la ITV: sensor de temperatura del refrigerante, luego sonda lambda.", "par": null}, {"texto": "Ralentí bajo o inestable, o se cala al soltar el acelerador: motor paso a paso o cuerpo de mariposa sucio. Si falla el motor paso a paso, la centralita limita a 1200 rpm.", "par": null}, {"texto": "Tirones y petardeos por el escape (SPI de Fiat): bujías, cables y bobinas; después, la presión de gasolina.", "par": null}, {"texto": "Golpeteo de taqués: cambiar el aceite (con limpiador); si sigue, cambiar los taqués hidráulicos.", "par": null}, {"texto": "Tras montar la culata funciona mal (bujías negras y húmedas): taqués hidráulicos sin purgar o bloqueados.", "par": null}, {"texto": "Centralita de desguace que no arranca: el inmovilizador (solo IAW 16S.S0).", "par": null}, {"texto": "Fallos intermitentes: revisar conectores y masas antes de cambiar piezas.", "par": null}]', 'Experiencia de usuarios del 899 SPI (fiabilidad C): orden lógico para buscar la avería.' FROM `vehiculos` v WHERE v.`id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB'))
AND NOT EXISTS (SELECT 1 FROM `procedimientos` x WHERE x.`vehiculo_id` = v.`id` AND x.`titulo` = 'Averías típicas del motor SPI');
--> statement-breakpoint
INSERT INTO `procedimientos` (`vehiculo_id`, `titulo`, `tiempo_min`, `herramientas`, `pasos`, `notas`)
SELECT v.`id`, 'Arranque de emergencia del inmovilizador', 5, '["Tarjeta de código (5 cifras)"]', '[{"texto": "Da el contacto y espera a que el testigo de inyección parpadee.", "par": null}, {"texto": "Para cada cifra del código: pisa el acelerador a fondo y suéltalo al contar en los destellos la cifra que toca.", "par": null}, {"texto": "Repite con las 5 cifras. Si el código es correcto, el testigo se apaga y el motor arranca.", "par": null}, {"texto": "Haz una copia de la llave cuanto antes: el transpondedor es de código fijo (TEMIC 11 o Philips ID33) y un cerrajero lo copia de una llave buena.", "par": null}]', 'Procedimiento de la IAW 16F y del Fiat CODE (fiabilidad C): no está confirmado que SEAT entregara tarjeta con el Marbella. Busca una tarjeta de plástico con la documentación del coche.' FROM `vehiculos` v WHERE v.`id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB'))
AND NOT EXISTS (SELECT 1 FROM `procedimientos` x WHERE x.`vehiculo_id` = v.`id` AND x.`titulo` = 'Arranque de emergencia del inmovilizador');
--> statement-breakpoint
INSERT INTO `procedimientos` (`vehiculo_id`, `titulo`, `tiempo_min`, `herramientas`, `pasos`, `notas`)
SELECT v.`id`, 'Cambio de aceite y filtro', 45, '["Bandeja de aceite", "Llave del tapón del cárter", "Llave de filtro", "Embudo"]', '[{"texto": "Calienta el motor unos minutos y pon el coche en llano.", "par": null}, {"texto": "Quita el tapón del cárter y deja vaciar.", "par": null}, {"texto": "Cambia el filtro (Mann W 714/2): junta untada con aceite, apriete a mano.", "par": null}, {"texto": "Pon el tapón del cárter con arandela nueva.", "par": "30 N·m (fiab. C)"}, {"texto": "Llena con 15W-40 o 10W-40 API SG o superior: 3,6 L con filtro (3,4 L sin filtro).", "par": null}, {"texto": "Arranca, deja al ralentí 1 minuto, para y comprueba el nivel con la varilla. Si los taqués golpetean al principio, deja que se llenen al ralentí.", "par": null}]', 'Pasos generales del taller con los datos de la ficha. Cada 5.000 km o 12 meses: los taqués hidráulicos son sensibles al aceite viejo.' FROM `vehiculos` v WHERE v.`id` = (SELECT CASE WHEN COUNT(*) = 1 THEN MAX(`id`) END FROM `vehiculos` WHERE lower(`alias`) LIKE '%marbella%' OR lower(coalesce(`modelo`, '')) LIKE '%marbella%' OR replace(replace(upper(`matricula`), '-', ''), ' ', '') IN ('A9742DB', 'A9748DB'))
